INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP2023_Chapter09.pdf', '9', 'Promoting Cross Border Trade in Digital Economy', '9.02', 'E-COMMERCE EXPORT HUBs (ECEHs)', 'Application for creation/notification of an ECEH area shall be made
to the DGFT.', 'Indha E-COMMERCE EXPORT HUBs (ECEHs) section-la, application for creation/notification of an ECEH area kandippa be made
to the DGFT.', '9.02 E-COMMERCE EXPORT HUBs (ECEHs)
a) Creation of ECEH
i. Application for creation/notification of an ECEH area shall be made
to the DGFT. ii.', 'E-COMMERCE EXPORT HUBs (ECEHs) governs how DGFT business controls should be applied, validated, and enforced.', 'E-COMMERCE EXPORT HUBs (ECEHs) explains the operating rule set that DEKAI should enforce. Key control points include Application for creation/notification of an ECEH area shall be made
to the DGFT.', 'Indha E-COMMERCE EXPORT HUBs (ECEHs) section-la, E-COMMERCE export HUBs (ECEHs) explains the operating rule set that DEKAI should enforce. Key control points include application for creation/notification of an ECEH area kandippa be made
to the DGFT.', '9.02 E-COMMERCE EXPORT HUBs (ECEHs)
a) Creation of ECEH
i. Application for creation/notification of an ECEH area shall be made
to the DGFT.
ii. The authority for approval for an ECEH vests with the DGFT. DGFT
shall constitute a committee for evaluation of ECEH applications. The
Committee shall have a member from the Department of Revenue besides
any other members as required from time-to-time.
iii. DGFT may specify export products or markets, which shall not be
eligible for ECEH operations. The negative list of items that cannot be dealt
within the ECEHs shall be notified separately.
b) Administration of ECEH
i. The ECEH developer shall provide an annual statement of accounts as
per instructions in this regard.
ii. DGFT shall notify procedures for supervision and inspections at
ECEHs. An independent evaluation and assessment mechanism may also be
developed.
